(A/'js/pieces.js').write_text(PIECES,encoding='utf-8')
p=A/'index.html';s=p.read_text(encoding='utf-8')
s=s.replace('<use href="#wN"/></svg></div>\n  <div class="splash-name">','<use href="#cb-mark"/></svg></div>\n  <div class="splash-name">',1)
s=s.replace('<div class="logo"><svg viewBox="0 0 45 45" aria-hidden="true"><use href="#wN"/></svg></div>','<div class="logo"><svg viewBox="0 0 45 45" aria-hidden="true"><use href="#cb-mark"/></svg></div>',1)
s=s.replace('<div class="home-piece">♞</div>','<div class="home-piece"><svg viewBox="0 0 45 45" aria-hidden="true"><use href="#wN"/></svg></div>',1)
s=s.replace('<div class="field"><label>Board colours</label><div class="seg" id="themeSeg"><button type="button" data-v="green">Green</button><button type="button" data-v="brown">Brown</button><button type="button" data-v="blue">Blue</button></div></div>','<div class="field"><label>Board palette</label><div class="seg cb-theme-picker" id="themeSeg"><button type="button" data-v="green">Emerald</button><button type="button" data-v="brown">Walnut</button><button type="button" data-v="blue">Arctic</button><button type="button" data-v="rose">Rose</button><button type="button" data-v="midnight">Midnight</button><button type="button" data-v="parchment">Parchment</button></div></div>',1)
p.write_text(s,encoding='utf-8')
css=A/'css/app.css';c=css.read_text(encoding='utf-8');marker='/* ChessBuddy Atelier artwork system v1 */'
if marker not in c:c+='''\n\n/* ChessBuddy Atelier artwork system v1 */\n:root{--sq-light:#e9eadc;--sq-dark:#62876a;--brand-ink:#14261f;--brand-gold:#d9b76d}\nbody[data-theme=green]{--sq-light:#e9eadc;--sq-dark:#62876a}\nbody[data-theme=brown]{--sq-light:#f0dfc4;--sq-dark:#9a704e}\nbody[data-theme=blue]{--sq-light:#e7eff2;--sq-dark:#7395a8}\nbody[data-theme=rose]{--sq-light:#f4e5e4;--sq-dark:#bd858b}\nbody[data-theme=midnight]{--sq-light:#8c9aa4;--sq-dark:#3a4d5b}\nbody[data-theme=parchment]{--sq-light:#f5edda;--sq-dark:#c4ad7d}\n.board{border-radius:7px;box-shadow:0 8px 22px #0003,0 0 0 1px #0002}\n.sq.light,.sq.dark{background-image:linear-gradient(145deg,#ffffff0c,transparent 58%)}\n.sq svg.pc{filter:drop-shadow(0 1px 1px #0004)}\n.logo{background:linear-gradient(145deg,#1d3c30,#10251f);box-shadow:0 3px 0 #091a14,0 5px 12px #0004}\n.logo svg{width:28px;height:28px}.splash-mark{background:linear-gradient(145deg,#244b3a,#10251f);box-shadow:0 7px 0 #091a14,0 18px 44px #0006}.splash-mark svg{width:60px;height:60px}\n.home-piece svg{width:116px;height:116px;filter:drop-shadow(0 8px 8px #0006)}\n.cb-theme-picker{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}\n.cb-theme-picker button{min-height:38px;border:1px solid var(--line);border-radius:9px;background:var(--surface2);font-size:12px;font-weight:750}\n.cb-theme-picker button[data-v=green]{box-shadow:inset 0 -5px 0 #62876a}.cb-theme-picker button[data-v=brown]{box-shadow:inset 0 -5px 0 #9a704e}.cb-theme-picker button[data-v=blue]{box-shadow:inset 0 -5px 0 #7395a8}.cb-theme-picker button[data-v=rose]{box-shadow:inset 0 -5px 0 #bd858b}.cb-theme-picker button[data-v=midnight]{box-shadow:inset 0 -5px 0 #3a4d5b}.cb-theme-picker button[data-v=parchment]{box-shadow:inset 0 -5px 0 #c4ad7d}\n.cb-theme-picker button.on{outline:2px solid var(--brand-gold);outline-offset:1px;color:var(--text)}\n@media(max-width:390px){.cb-theme-picker{grid-template-columns:repeat(2,minmax(0,1fr))}}\n''';css.write_text(c,encoding='utf-8')
fg=Path('app/src/main/res/drawable/ic_launcher_foreground.xml');fg.write_text('''<?xml version="1.0" encoding="utf-8"?>\n<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="108dp" android:height="108dp" android:viewportWidth="45" android:viewportHeight="45">\n<path android:fillColor="#F3E6C7" android:strokeColor="#D9B76D" android:strokeWidth="1.1" android:pathData="M22.5,2.5 L40,9 L40,21.8 C40,32 33.1,38.5 22.5,42.8 C11.9,38.5 5,32 5,21.8 L5,9 Z"/>\n<path android:fillColor="#10251F" android:pathData="M12,31.8 L34,31.8 L32,28.6 L32,16.2 L28,11 L24.5,16.2 L22.5,11.5 L20.5,16.2 L17,11 L13,16.2 L13,28.6 Z"/>\n<path android:fillColor="#00000000" android:strokeColor="#D9B76D" android:strokeWidth="1.2" android:pathData="M16,22 L29,22 M17,26 L28,26"/>\n<path android:fillColor="#F3E6C7" android:pathData="M27.1,18.5a1.1,1.1 0,1 0,2.2 0a1.1,1.1 0,1 0,-2.2 0"/>\n</vector>\n''',encoding='utf-8')
