(art/'brand-mark.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 45 45"><path fill="#10251f" d="M22.5 2.5 40 9v12.8c0 10.2-6.9 16.7-17.5 21C11.9 38.5 5 32 5 21.8V9Z"/><path fill="#f3e6c7" stroke="#d9b76d" stroke-width="1.1" d="M12 31.8h22l-2-3.2V16.2l-4-5.2-3.5 5.2-2-4.7-2 4.7-3.5-5.2-4 5.2v12.4Z"/><path fill="none" stroke="#94764c" stroke-width="1.2" d="M16 22h13M17 26h11"/></svg>',encoding='utf-8')
